/** Public Umami share (Hobby / free) — no paid API key required. */
export const UMAMI_WEBSITE_ID =
  process.env.REACT_APP_UMAMI_WEBSITE_ID ||
  "be0902b7-eca2-4d8e-a436-5ade90cca757";

/** Share slug from https://cloud.umami.is/share/<slug> */
export const UMAMI_SHARE_ID =
  process.env.REACT_APP_UMAMI_SHARE_ID || "H0CPakgCeWFDHHug";

export const UMAMI_SHARE_URL =
  process.env.REACT_APP_UMAMI_SHARE_URL ||
  `https://cloud.umami.is/share/${UMAMI_SHARE_ID}`;

/** Account data region: eu | us */
export const UMAMI_REGION = (
  process.env.REACT_APP_UMAMI_REGION || "eu"
).toLowerCase();
