import { useEffect, useState } from "react";
import { fetchAllStats, getShareId } from "../lib/umamiApi";

export function useUmamiStats() {
  const [state, setState] = useState({
    loading: Boolean(getShareId()),
    error: null,
    summary: null,
    active: null,
    countries: [],
    pages: [],
  });

  useEffect(() => {
    if (!getShareId()) {
      setState((s) => ({ ...s, loading: false, error: "no_share" }));
      return;
    }

    let cancelled = false;

    (async () => {
      try {
        const data = await fetchAllStats();
        if (cancelled) return;
        setState({
          loading: false,
          error: null,
          summary: data.summary,
          active: data.active,
          countries: data.countries,
          pages: data.pages,
        });
      } catch {
        if (cancelled) return;
        setState({
          loading: false,
          error: "fetch_failed",
          summary: null,
          active: null,
          countries: [],
          pages: [],
        });
      }
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  return state;
}
