import {
  UMAMI_REGION,
  UMAMI_SHARE_ID,
  UMAMI_SHARE_URL,
  UMAMI_WEBSITE_ID,
} from "../config/umami";

function range30d() {
  const endAt = Date.now();
  const startAt = endAt - 30 * 24 * 60 * 60 * 1000;
  return { startAt, endAt };
}

function qs(params) {
  return new URLSearchParams(
    Object.entries(params).map(([k, v]) => [k, String(v)])
  ).toString();
}

function apiBase(region) {
  const r = (region || UMAMI_REGION || "eu").toLowerCase();
  return `https://cloud.umami.is/analytics/${r}/api`;
}

function shareHeaders(token) {
  return {
    Accept: "application/json",
    "X-Umami-Share-Token": token,
    "X-Umami-Share-Context": "share",
  };
}

function asList(data) {
  if (Array.isArray(data)) return data;
  if (data && typeof data === "object" && data.x != null) return [data];
  return [];
}

function unwrapStats(data) {
  if (!data || typeof data !== "object") return data;
  // Support both flat and { pageviews: { value } } shapes
  const n = (v) => (v && typeof v === "object" && "value" in v ? v.value : v);
  return {
    pageviews: n(data.pageviews),
    visitors: n(data.visitors),
    visits: n(data.visits),
    bounces: n(data.bounces),
    totaltime: n(data.totaltime),
  };
}

async function fetchShareAuth(shareId = UMAMI_SHARE_ID) {
  const regions = [
    UMAMI_REGION,
    UMAMI_REGION === "eu" ? "us" : "eu",
  ].filter((v, i, a) => v && a.indexOf(v) === i);

  let lastError;
  for (const region of regions) {
    const url = `${apiBase(region)}/share/${shareId}`;
    try {
      const res = await fetch(url, { headers: { Accept: "application/json" } });
      if (!res.ok) {
        lastError = new Error(`share_${res.status}`);
        continue;
      }
      const data = await res.json();
      if (!data?.token) {
        lastError = new Error("share_no_token");
        continue;
      }
      return {
        token: data.token,
        websiteId: data.websiteId || UMAMI_WEBSITE_ID,
        region,
      };
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError || new Error("share_unreachable");
}

async function shareGet(path, auth, params = {}) {
  const query = qs({ ...range30d(), ...params });
  const url = `${apiBase(auth.region)}${path}?${query}`;
  const res = await fetch(url, { headers: shareHeaders(auth.token) });
  if (!res.ok) throw new Error(`umami_${res.status}`);
  return res.json();
}

export function getWebsiteId() {
  return UMAMI_WEBSITE_ID;
}

export function getShareUrl() {
  return UMAMI_SHARE_URL;
}

export function getShareId() {
  return UMAMI_SHARE_ID;
}

/** @deprecated Paid API key no longer used — share token is free. */
export function getApiKey() {
  return "";
}

export async function fetchAllStats() {
  const auth = await fetchShareAuth();
  const websiteId = auth.websiteId;

  const [summaryRaw, active, countriesRaw, pagesRaw] = await Promise.all([
    shareGet(`/websites/${websiteId}/stats`, auth),
    shareGet(`/websites/${websiteId}/active`, auth).catch(() => ({
      visitors: 0,
    })),
    shareGet(`/websites/${websiteId}/metrics`, auth, {
      type: "country",
      limit: 12,
    }),
    shareGet(`/websites/${websiteId}/metrics`, auth, {
      type: "path",
      limit: 10,
    }),
  ]);

  return {
    summary: unwrapStats(summaryRaw),
    active: active || { visitors: 0 },
    countries: asList(countriesRaw),
    pages: asList(pagesRaw),
  };
}
